import{_ as d,o as a,c as r,a2 as o}from"./chunks/framework.CqpfiAoK.js";const s=JSON.parse('{"title":"সেটিং দ্বন্দ্ব স্ব-পরীক্ষা টেবিল","description":"","frontmatter":{},"headers":[],"relativePath":"bn/97-设定矛盾自查表.md","filePath":"bn/97-设定矛盾自查表.md","lastUpdated":null}'),e={name:"bn/97-设定矛盾自查表.md"};function h(l,t,i,u,n,q){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="সেটিং-দ্বন্দ্ব-স্ব-পরীক্ষা-টেবিল" tabindex="-1">সেটিং দ্বন্দ্ব স্ব-পরীক্ষা টেবিল <a class="header-anchor" href="#সেটিং-দ্বন্দ্ব-স্ব-পরীক্ষা-টেবিল" aria-label="Permalink to &quot;সেটিং দ্বন্দ্ব স্ব-পরীক্ষা টেবিল&quot;">​</a></h1><table tabindex="0"><thead><tr><th>আইটেম</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>97</td></tr><tr><td>মডিউল</td><td>পরিশিষ্ট ও রেফারেন্স উপকরণ</td></tr><tr><td>মূল শব্দগুলি</td><td>দ্বন্দ্ব স্ব-পরীক্ষা, সেটিং সামঞ্জস্য, যৌক্তিক যাচাই, মান নিয়ন্ত্রণ, সেটিং রক্ষণাবেক্ষণ</td></tr></tbody></table><h2 id="১-বিবরণ" tabindex="-1">১. বিবরণ <a class="header-anchor" href="#১-বিবরণ" aria-label="Permalink to &quot;১. বিবরণ&quot;">​</a></h2><p>সেটিং দ্বন্দ্ব স্ব-পরীক্ষা টেবিল হলো অ্যাঙ্কর সিম্বায়োসিস সভ্যতার সেটিং সিস্টেমের মান নিয়ন্ত্রণ সরঞ্জাম, যা নতুন সেটিং তৈরি, পুরানো সেটিং সংশোধন এবং নথি আপডেটের সময় সম্ভাব্য সেটিং দ্বন্দ্ব এবং যৌক্তিক অসঙ্গতিকে পদ্ধতিগতভাবে সনাক্ত করতে ব্যবহৃত হয়। এই স্ব-পরীক্ষা টেবিলটি SPEC.md-এ প্রতিষ্ঠিত 14টি মূল সেটিং এবং সামঞ্জস্য পরীক্ষা তালিকার উপর ভিত্তি করে প্রস্তুত করা হয়েছে, এবং বিশ্বদৃষ্টিভঙ্গি, ক্ষতি ব্যবস্থা, সামাজিক ব্যবস্থা, আইনি ব্যবস্থা, জীবনের রূপ, প্রযুক্তি ব্যবস্থা, ঐতিহাসিক যুগ, আন্তঃসমতল মিথস্ক্রিয়া ইত্যাদি সমস্ত মডিউলকে কভার করে। কোনো নতুন সেটিং বা সংশোধিত বিষয়বস্তু আনুষ্ঠানিকভাবে সেটিং সিস্টেমে অন্তর্ভুক্ত করার আগে, অবশ্যই এই স্ব-পরীক্ষা টেবিলের সমস্ত পরীক্ষা পাস করতে হবে।</p><h2 id="২-মূল-সেটিং-সামঞ্জস্য-পরীক্ষা" tabindex="-1">২. মূল সেটিং সামঞ্জস্য পরীক্ষা <a class="header-anchor" href="#২-মূল-সেটিং-সামঞ্জস্য-পরীক্ষা" aria-label="Permalink to &quot;২. মূল সেটিং সামঞ্জস্য পরীক্ষা&quot;">​</a></h2><h3 id="২-১-মহাবিশ্বের-নাম-এবং-মূল-ধারণা" tabindex="-1">২.১ মহাবিশ্বের নাম এবং মূল ধারণা <a class="header-anchor" href="#২-১-মহাবিশ্বের-নাম-এবং-মূল-ধারণা" aria-label="Permalink to &quot;২.১ মহাবিশ্বের নাম এবং মূল ধারণা&quot;">​</a></h3><table tabindex="0"><thead><tr><th>পরীক্ষা আইটেম</th><th>পরীক্ষা বিষয়বস্তু</th><th>পাসের মানদণ্ড</th><th>সাধারণ সমস্যা</th></tr></thead><tbody><tr><td>C01</td><td>মহাবিশ্বের নাম একীভূত কিনা</td><td>সম্পূর্ণ পাঠে &quot;ওয়ান লিং হেঙ্গ মাও বেন ইয়ান ঝো&quot; বা সংক্ষিপ্ত &quot;হেঙ্গুয়ানঝো&quot; ব্যবহার করা হয়, অন্য কোনো নাম ব্যবহার করা যাবে না</td><td>&quot;মহাবিশ্ব&quot;, &quot;দস হাজার জগত&quot;, &quot;স্বর্গের দস জগত&quot; ইত্যাদি অমানক নামের মিশ্রণ</td></tr><tr><td>C02</td><td>অ্যাঙ্কারের সংজ্ঞা সামঞ্জস্যপূর্ণ কিনা</td><td>অ্যাঙ্কার সর্বদা &quot;শেরিয়া নেটওয়ার্কের স্থিতিশীল নোড&quot; হিসেবে সংজ্ঞায়িত, এর মৌলিক বৈশিষ্ট্য পরিবর্তন করা যাবে না</td><td>অ্যাঙ্কারকে বস্তু, জীব বা শক্তি সত্তা হিসেবে বর্ণনা করা</td></tr><tr><td>C03</td><td>সিম্বায়োসিস ধারণা একীভূত কিনা</td><td>সিম্বায়োসিস সর্বদা &quot;বিভিন্ন জীবনের মধ্যে পারস্পরিক উপকারী সহযোগিতার মাধ্যমে সাধারণ বিবর্তন&quot; বোঝায়, লুণ্ঠন বিরোধী অবস্থান থেকে বিচ্যুত হবে না</td><td>সিম্বায়োসিসকে সমীকরণ, গ্রাস বা নিয়ন্ত্রণ হিসেবে বর্ণনা করা</td></tr><tr><td>C04</td><td>মূল অবস্থান একীভূত কিনা</td><td>সর্বদা &quot;বাস্তবতাকে ভিত্তি হিসেবে&quot; নীতি মেনে চলা, কাল্পনিক সেটিংকে বাস্তব হিসেবে বর্ণনা করা যাবে না</td><td>কাল্পনিক এবং বাস্তবের সীমানা বিভ্রান্ত করা</td></tr></tbody></table><h3 id="২-২-ক্ষতি-ব্যবস্থার-সামঞ্জস্য" tabindex="-1">২.২ ক্ষতি ব্যবস্থার সামঞ্জস্য <a class="header-anchor" href="#২-২-ক্ষতি-ব্যবস্থার-সামঞ্জস্য" aria-label="Permalink to &quot;২.২ ক্ষতি ব্যবস্থার সামঞ্জস্য&quot;">​</a></h3><table tabindex="0"><thead><tr><th>পরীক্ষা আইটেম</th><th>পরীক্ষা বিষয়বস্তু</th><th>পাসের মানদণ্ড</th><th>সাধারণ সমস্যা</th></tr></thead><tbody><tr><td>C05</td><td>ব্যবস্থার মোট সংখ্যা সামঞ্জস্যপূর্ণ কিনা</td><td>মূল ক্ষতি ব্যবস্থার মোট সংখ্যা সর্বদা তিনশত সেট, বাড়ানো বা কমানো যাবে না</td><td>&quot;তিনশতেরও বেশি সেট&quot;, &quot;কয়েকশত সেট&quot; ইত্যাদি অস্পষ্ট বিবৃতি প্রদর্শিত</td></tr><tr><td>C06</td><td>ব্যবস্থার শ্রেণীবিভাগ সামঞ্জস্যপূর্ণ কিনা</td><td>সর্বদা ছয়টি শ্রেণীতে বিভক্ত (মূল অনুমান, জীবন চক্র, স্থান শেরিয়া, চেতনা মাত্রা বৃদ্ধি, সিম্বায়োসিস নেটওয়ার্ক, প্রয়োগ প্রকৌশল), প্রতি শ্রেণীতে পঞ্চাশ সেট</td><td>অন্য শ্রেণীবিভাগ পদ্ধতি বা শ্রেণীর সংখ্যার অসঙ্গতি প্রদর্শিত</td></tr><tr><td>C07</td><td>মূল তিন ভিত্তি সামঞ্জস্যপূর্ণ কিনা</td><td>প্রথম তিনটি সেট সর্বদা অনুমান পুনরাবৃত্তি (001), জীবন চক্র (002), স্থান শেরিয়া পরিচালনা (003)</td><td>প্রথম তিনটি সেটের নম্বর বা নাম পরিবর্তন করা</td></tr><tr><td>C08</td><td>বেই জেঙ ফলের সেটিং সামঞ্জস্যপূর্ণ কিনা</td><td>বেই জেঙ ফল সর্বদা &quot;শুরুর বাফ&quot;, শতগুণ অনুমান বৃদ্ধি প্রদান করে, ইতিমধ্যে প্রযুক্তিগতভাবে প্রয়োগ করা হয়েছে</td><td>বেই জেঙ ফলকে প্রাকৃতিক ফল বা অপ্রযুক্তিগত হিসেবে বর্ণনা করা</td></tr><tr><td>C09</td><td>ক্ষতি সীমা সামঞ্জস্যপূর্ণ কিনা</td><td>প্রতিটি ব্যবস্থার সীমার বিভাজন নথি 14 &quot;ক্ষতি সীমার ঐক্য বিভাজন&quot; এর সাথে সামঞ্জস্যপূর্ণ</td><td>ঐক্য বিভাজনের সাথে দ্বন্দ্বপূর্ণ সীমার নাম নিজে থেকে উদ্ভাবন করা</td></tr><tr><td>C10</td><td>লুণ্ঠন বিরোধী অবস্থান সামঞ্জস্যপূর্ণ কিনা</td><td>লুণ্ঠনশৈলী ক্ষতিকে ইতিবাচক বা গ্রহণযোগ্য ব্যবস্থা হিসেবে বর্ণনা করা যাবে না</td><td>লুণ্ঠনশৈলী ক্ষতির পক্ষে যুক্তি দেওয়া বা সুন্দর করা</td></tr></tbody></table><h3 id="২-৩-সামাজিক-এবং-আইনি-সামঞ্জস্য" tabindex="-1">২.৩ সামাজিক এবং আইনি সামঞ্জস্য <a class="header-anchor" href="#২-৩-সামাজিক-এবং-আইনি-সামঞ্জস্য" aria-label="Permalink to &quot;২.৩ সামাজিক এবং আইনি সামঞ্জস্য&quot;">​</a></h3><table tabindex="0"><thead><tr><th>পরীক্ষা আইটেম</th><th>পরীক্ষা বিষয়বস্তু</th><th>পাসের মানদণ্ড</th><th>সাধারণ সমস্যা</th></tr></thead><tbody><tr><td>C11</td><td>সভ্যতার বিভাজন সামঞ্জস্যপূর্ণ কিনা</td><td>সর্বদা পাঁচটি বিভাজন (পূর্ব এশিয়া সংকুচিত, উত্তর ইউরোপ কল্যাণ, উত্তর আমেরিকা বহুমুখী, ইউরোপীয় মহাদেশ সামাজিক, উন্নয়নশীল অতিক্রমকারী)</td><td>ষষ্ঠ বিভাজন প্রদর্শিত বা বিভাজনের নাম পরিবর্তন করা</td></tr><tr><td>C12</td><td>আইনি ব্যবস্থা সামঞ্জস্যপূর্ণ কিনা</td><td>সর্বদা সংবিধান + শ্রম আইন + ভোক্তা সুরক্ষা আইন + পাঁচটি সহায়ক আইন (শিক্ষা, স্বাস্থ্য, আবাসন, পরিবেশ, একচেটিয়া বিরোধী)</td><td>কোনো আইন বাদ দেওয়া বা অসেট করা আইন যোগ করা</td></tr><tr><td>C13</td><td>পরিচালনা কাঠামো সামঞ্জস্যপূর্ণ কিনা</td><td>সর্বদা অ্যাঙ্কার পরিষদ (আইনপ্রণয়ন) + সিম্বায়োসিস কার্যকরী কমিটি (প্রশাসন) + সিম্বায়োসিস আদালত (বিচার) + অ্যাঙ্কার তদারকি কমিটি (তদারকি)</td><td>প্রতিষ্ঠানের নাম বা ক্ষমতা বণ্টন পরিবর্তন করা</td></tr><tr><td>C14</td><td>যৌথ উৎপাদন চুক্তি মেকানিজম সামঞ্জস্যপূর্ণ কিনা</td><td>সর্বদা &quot;বেশি পরিশ্রম বেশি লাভ&quot;কে কেন্দ্র করে, সম্পদ বণ্টন অবদানের উপর ভিত্তি করে</td><td>যৌথ উৎপাদন চুক্তিকে গড়বাদ বা প্রয়োজন অনুযায়ী বণ্টন হিসেবে বর্ণনা করা</td></tr><tr><td>C15</td><td>20% সক্রিয়করণ কৌশল সামঞ্জস্যপূর্ণ কিনা</td><td>সর্বদা প্রাথমিক পর্যায়ে 20% সত্ত্বকে সমতল সর্বোচ্চ শক্তিশালী হিসেবে সক্রিয় করা</td><td>সক্রিয়করণের অনুপাত বা লক্ষ্য পরিবর্তন করা</td></tr></tbody></table><h2 id="৩-ক্রস-মডিউল-যৌক্তিক-সামঞ্জস্য-পরীক্ষা" tabindex="-1">৩. ক্রস-মডিউল যৌক্তিক সামঞ্জস্য পরীক্ষা <a class="header-anchor" href="#৩-ক্রস-মডিউল-যৌক্তিক-সামঞ্জস্য-পরীক্ষা" aria-label="Permalink to &quot;৩. ক্রস-মডিউল যৌক্তিক সামঞ্জস্য পরীক্ষা&quot;">​</a></h2><h3 id="৩-১-সময়রেখার-সামঞ্জস্য" tabindex="-1">৩.১ সময়রেখার সামঞ্জস্য <a class="header-anchor" href="#৩-১-সময়রেখার-সামঞ্জস্য" aria-label="Permalink to &quot;৩.১ সময়রেখার সামঞ্জস্য&quot;">​</a></h3><table tabindex="0"><thead><tr><th>পরীক্ষা আইটেম</th><th>পরীক্ষা বিষয়বস্তু</th><th>পাসের মানদণ্ড</th><th>সাধারণ সমস্যা</th></tr></thead><tbody><tr><td>L01</td><td>ঐতিহাসিক ঘটনার সময় সামঞ্জস্যপূর্ণ কিনা</td><td>সমস্ত ঐতিহাসিক ঘটনার সময় নথি 93 &quot;ক্রনিকল সারসংক্ষেপ&quot; এবং নথি 70-79 এর সাথে সামঞ্জস্যপূর্ণ</td><td>একই ঘটনা বিভিন্ন নথিতে সময় অসঙ্গতিপূর্ণ</td></tr><tr><td>L02</td><td>যুগের বিভাজন সামঞ্জস্যপূর্ণ কিনা</td><td>যুগের নাম এবং শুরু-শেষের সময় নথি 70 &quot;যুগ বিভাজন সারসংক্ষেপ টেবিল&quot; এর সাথে সামঞ্জস্যপূর্ণ</td><td>অসেট করা যুগ প্রদর্শিত বা যুগের সীমানা পরিবর্তন করা</td></tr><tr><td>L03</td><td>ব্যক্তির যুগ সামঞ্জস্যপূর্ণ কিনা</td><td>গুরুত্বপূর্ণ ব্যক্তিদের সক্রিয় যুগ নথি 95 &quot;গুরুত্বপূর্ণ ব্যক্তি এবং সংস্থা&quot; এর সাথে সামঞ্জস্যপূর্ণ</td><td>ব্যক্তি তার অস্তিত্বহীন যুগে উপস্থিত</td></tr><tr><td>L04</td><td>প্রযুক্তির আবির্ভাবের সময় সামঞ্জস্যপূর্ণ কিনা</td><td>প্রতিটি প্রযুক্তির উদ্ভাবন এবং পরিপক্কতার সময় ক্রনিকলের সাথে সামঞ্জস্যপূর্ণ</td><td>কোনো প্রযুক্তি তার উদ্ভাবনের আগের যুগে ব্যবহৃত হয়</td></tr></tbody></table><h3 id="৩-২-প্রযুক্তি-ব্যবস্থার-সামঞ্জস্য" tabindex="-1">৩.২ প্রযুক্তি ব্যবস্থার সামঞ্জস্য <a class="header-anchor" href="#৩-২-প্রযুক্তি-ব্যবস্থার-সামঞ্জস্য" aria-label="Permalink to &quot;৩.২ প্রযুক্তি ব্যবস্থার সামঞ্জস্য&quot;">​</a></h3><table tabindex="0"><thead><tr><th>পরীক্ষা আইটেম</th><th>পরীক্ষা বিষয়বস্তু</th><th>পাসের মানদণ্ড</th><th>সাধারণ সমস্যা</th></tr></thead><tbody><tr><td>T01</td><td>প্রতিলিপি দর্পণ প্রযুক্তি সামঞ্জস্যপূর্ণ কিনা</td><td>প্রতিলিপি দর্পণ সর্বদা &quot;মূল বস্তু স্পর্শ না করা 1:1 প্রতিলিপি ডিভাইস&quot;, প্রতিলিপি প্রক্রিয়া শূন্য হস্তক্ষেপ</td><td>প্রতিলিপি দর্পণকে মূল বস্তু পরিবর্তন করতে সক্ষম বা মূল বস্তু স্পর্শ করতে হবে এমন হিসেবে বর্ণনা করা</td></tr><tr><td>T02</td><td>বিচ্ছিন্ন স্থান সামঞ্জস্যপূর্ণ কিনা</td><td>বিচ্ছিন্ন স্থান সর্বদা &quot;বাইরের থেকে শেরিয়া প্রাচীর দ্বারা সম্পূর্ণভাবে বিচ্ছিন্ন স্বাধীন স্থান&quot;</td><td>বিচ্ছিন্ন স্থানকে সাধারণ ঘর বা ভার্চুয়াল স্থান হিসেবে বর্ণনা করা</td></tr><tr><td>T03</td><td>স্থান শেরিয়া ক্ষতির প্রয়োজনীয়তা সামঞ্জস্যপূর্ণ কিনা</td><td>প্রতিটি স্থান প্রযুক্তির ক্ষতির প্রয়োজনীয়তা নথি 13 &quot;স্থান শেরিয়া পরিচালনা ব্যবস্থার বিস্তারিত বিবরণ&quot; এর সাথে সামঞ্জস্যপূর্ণ</td><td>কম ক্ষতির ব্যক্তি উচ্চ ক্ষতির প্রয়োজনীয় প্রযুক্তি ব্যবহার করে</td></tr><tr><td>T04</td><td>শক্তির একক সামঞ্জস্যপূর্ণ কিনা</td><td>শক্তি পরিমাপ সর্বদা &quot;মানক শক্তি একক&quot; ব্যবহার করে, অন্য কোনো একক ব্যবহার করা যাবে না</td><td>&quot;আত্মা পাথর&quot;, &quot;স্ফটিক মুদ্রা&quot; ইত্যাদি অমানক শক্তি এককের মিশ্রণ</td></tr></tbody></table><h3 id="৩-৩-আন্তঃসমতল-এবং-সময়-নিয়মের-সামঞ্জস্য" tabindex="-1">৩.৩ আন্তঃসমতল এবং সময় নিয়মের সামঞ্জস্য <a class="header-anchor" href="#৩-৩-আন্তঃসমতল-এবং-সময়-নিয়মের-সামঞ্জস্য" aria-label="Permalink to &quot;৩.৩ আন্তঃসমতল এবং সময় নিয়মের সামঞ্জস্য&quot;">​</a></h3><table tabindex="0"><thead><tr><th>পরীক্ষা আইটেম</th><th>পরীক্ষা বিষয়বস্তু</th><th>পাসের মানদণ্ড</th><th>সাধারণ সমস্যা</th></tr></thead><tbody><tr><td>K01</td><td>প্রথমে পর্যবেক্ষণ করে তারপর সীমিত হস্তক্ষেপ সামঞ্জস্যপূর্ণ কিনা</td><td>সমস্ত সময় প্রত্যাবর্তন এবং আন্তঃসমতল অপারেশন অবশ্যই এই নীতি অনুসরণ করবে, পর্যবেক্ষণ পর্যায় এড়িয়ে চলা যাবে না</td><td>পর্যবেক্ষণ ছাড়াই সরাসরি হস্তক্ষেপের অপারেশন বর্ণনা করা</td></tr><tr><td>K02</td><td>শুধুমাত্র জ্ঞান ফেরত সামঞ্জস্যপূর্ণ কিনা</td><td>প্রত্নতত্ত্বের আউটপুট শুধুমাত্র বিমূর্ত জ্ঞান এবং তথ্যে সীমাবদ্ধ, পদার্থ, শক্তি বা জীব ফেরত পাঠানো যাবে না</td><td>প্রত্নতত্ত্বের নমুনা বা নমুনা নিজের সমতলে ফিরিয়ে আনার আচরণ বর্ণনা করা</td></tr><tr><td>K03</td><td>যাত্রা অনুমতি ব্যবস্থা সামঞ্জস্যপূর্ণ কিনা</td><td>সমস্ত সমতল যাত্রা অবশ্যই সংশ্লিষ্ট স্তরের অনুমতি প্রাপ্ত করবে, অনুমতি ছাড়া যাত্রা করা যাবে না</td><td>অনুমতি ছাড়াই নিজের ইচ্ছায় যাত্রা বর্ণনা করা</td></tr><tr><td>K04</td><td>সময় প্যারাডক্সের শ্রেণীবিভাগ সামঞ্জস্যপূর্ণ কিনা</td><td>প্যারাডক্স সর্বদা বংশধর হত্যা, তথ্য, স্বত্ব, ঘটনা চারটি শ্রেণীতে বিভক্ত, বাড়ানো বা পরিবর্তন করা যাবে না</td><td>অসেট করা প্যারাডক্সের ধরন প্রদর্শিত</td></tr><tr><td>K05</td><td>সমতলের শ্রেণীবিভাগ সামঞ্জস্যপূর্ণ কিনা</td><td>সমতল সর্বদা পাঁচটি শ্রেণীতে বিভক্ত (পদার্থিক মূল, শক্তি প্রকাশ, চেতনা প্রধান, শেরিয়া ভাঙা, মূল নিকটবর্তী)</td><td>অন্য শ্রেণীবিভাগ পদ্ধতি প্রদর্শিত</td></tr></tbody></table><h3 id="৩-৪-জীবন-এবং-জাতির-সামঞ্জস্য" tabindex="-1">৩.৪ জীবন এবং জাতির সামঞ্জস্য <a class="header-anchor" href="#৩-৪-জীবন-এবং-জাতির-সামঞ্জস্য" aria-label="Permalink to &quot;৩.৪ জীবন এবং জাতির সামঞ্জস্য&quot;">​</a></h3><table tabindex="0"><thead><tr><th>পরীক্ষা আইটেম</th><th>পরীক্ষা বিষয়বস্তু</th><th>পাসের মানদণ্ড</th><th>সাধারণ সমস্যা</th></tr></thead><tbody><tr><td>S01</td><td>জাতির শ্রেণীবিভাগ সামঞ্জস্যপূর্ণ কিনা</td><td>জাতি সর্বদা আটটি শ্রেণীতে বিভক্ত (মানব রূপ, প্রাণী রূপ, উদ্ভিদ রূপ, মৌলিক রূপ, শক্তি রূপ, চেতনা রূপ, যান্ত্রিক রূপ, মিশ্রিত রূপ)</td><td>অন্য শ্রেণীবিভাগ পদ্ধতি প্রদর্শিত</td></tr><tr><td>S02</td><td>অদ্ভুত জীবনের ব্যবস্থাপনা সামঞ্জস্যপূর্ণ কিনা</td><td>অদ্ভুত জীবন সর্বদা তিনটি ধরনের মানক ব্যবস্থাপনা প্রক্রিয়া অনুসরণ করে</td><td>প্রক্রিয়া ছাড়াই নিজের ইচ্ছায় ব্যবস্থাপনা বর্ণনা করা</td></tr><tr><td>S03</td><td>অন্ধকার প্রতিস্থাপন সত্তার ব্যবস্থাপনা সামঞ্জস্যপূর্ণ কিনা</td><td>অন্ধকার প্রতিস্থাপন সত্তা সর্বদা দ্বৈত আত্মা নৈতিকতা এবং চারটি শাখার ব্যবস্থাপনা নিয়ম অনুসরণ করে</td><td>এক পক্ষের আত্মাকে সহজভাবে বিলোপ করার আচরণ বর্ণনা করা</td></tr><tr><td>S04</td><td>সব জাতির সমানতা সামঞ্জস্যপূর্ণ কিনা</td><td>সমস্ত বুদ্ধিমান জাতি আইনের সামনে সমান, জাতিগত বৈষম্যের সেটিং থাকতে পারবে না</td><td>কোনো জাতিকে সহজাত নিম্ন বা দাসত্বের যোগ্য হিসেবে বর্ণনা করা</td></tr></tbody></table><h2 id="৪-নথি-বিন্যাস-এবং-বিধি-পরীক্ষা" tabindex="-1">৪. নথি বিন্যাস এবং বিধি পরীক্ষা <a class="header-anchor" href="#৪-নথি-বিন্যাস-এবং-বিধি-পরীক্ষা" aria-label="Permalink to &quot;৪. নথি বিন্যাস এবং বিধি পরীক্ষা&quot;">​</a></h2><table tabindex="0"><thead><tr><th>পরীক্ষা আইটেম</th><th>পরীক্ষা বিষয়বস্তু</th><th>পাসের মানদণ্ড</th><th>সাধারণ সমস্যা</th></tr></thead><tbody><tr><td>F01</td><td>ফাইলের নামের বিন্যাস সঠিক কিনা</td><td>ফাইলের নামের বিন্যাস &quot;XX-নথির শিরোনাম.md&quot;, XX দুটি সংখ্যার নম্বর</td><td>নম্বর অনুপস্থিত, শিরোনামে ফাঁক জায়গা, ফাইলের এক্সটেনশন ভুল</td></tr><tr><td>F02</td><td>নথির তথ্য ব্লক সম্পূর্ণ কিনা</td><td>শুরুতে নম্বর, মডিউল, মূল শব্দগুলি (3-5টি) সহ তথ্য টেবিল অন্তর্ভুক্ত</td><td>তথ্য ব্লক অনুপস্থিত বা ক্ষেত্র অসম্পূর্ণ</td></tr><tr><td>F03</td><td>দ্বিতীয় স্তরের শিরোনামের সংখ্যা পর্যাপ্ত কিনা</td><td>মূল পাঠে অন্তত 3টি দ্বিতীয় স্তরের শিরোনাম অধ্যায় অন্তর্ভুক্ত</td><td>দ্বিতীয় স্তরের শিরোনাম 3টির কম</td></tr><tr><td>F04</td><td>কাঠামোগত উপাদান ব্যবহার করা হয়েছে কিনা</td><td>পঠনযোগ্যতা বাড়াতে তালিকা, টেবিল ইত্যাদি কাঠামোগত উপাদান ব্যবহার করা</td><td>শুধুমাত্র পাঠ্য অনুচ্ছেদ, কোনো তালিকা বা টেবিল নেই</td></tr><tr><td>F05</td><td>উপসংহার বিদ্যমান কিনা</td><td>শেষে &quot;উপসংহার&quot; অনুচ্ছেদ আছে</td><td>উপসংহার অনুপস্থিত</td></tr><tr><td>F06</td><td>সম্পর্কিত নথি বিদ্যমান কিনা</td><td>শেষে 2-3টি সম্পর্কিত নথির নম্বর এবং নাম তালিকাভুক্ত</td><td>সম্পর্কিত নথি অনুপস্থিত বা সম্পর্কিত নথি বিদ্যমান নেই</td></tr><tr><td>F07</td><td>শব্দের সংখ্যা পর্যাপ্ত কিনা</td><td>মূল পাঠ 800 শব্দের কম নয় (শিরোনাম এবং মেটা তথ্য বাদ দিয়ে)</td><td>মূল পাঠ 800 শব্দের কম</td></tr><tr><td>F08</td><td>শব্দার্থের ব্যবহার একীভূত কিনা</td><td>&quot;হেঙ্গুয়ানঝো&quot;, &quot;অ্যাঙ্কার&quot;, &quot;সিম্বায়োসিস&quot; ইত্যাদি মানক শব্দার্থ ব্যবহার করা</td><td>শব্দার্থ অসঙ্গতিপূর্ণ বা অমানক বিবৃতি ব্যবহার করা</td></tr><tr><td>F09</td><td>লেখার শৈলী উপযুক্ত কিনা</td><td>গুরুত্বপূর্ণ, কাঠামোগত সেটিং নথির শৈলী, কোনো মৌখিক অভিব্যক্তি নেই</td><td>মৌখিক, নিজের ইচ্ছায় অভিব্যক্তি প্রদর্শিত</td></tr><tr><td>F10</td><td>নম্বর তালিকার সাথে সামঞ্জস্যপূর্ণ কিনা</td><td>নথির নম্বর এবং শিরোনাম SPEC.md-এর 100টি নথির সম্পূর্ণ তালিকার সাথে সামঞ্জস্যপূর্ণ</td><td>নম্বর বা শিরোনাম তালিকার সাথে মেলে না</td></tr></tbody></table><h2 id="৫-স্ব-পরীক্ষা-প্রক্রিয়া-এবং-ব্যবহার-পদ্ধতি" tabindex="-1">৫. স্ব-পরীক্ষা প্রক্রিয়া এবং ব্যবহার পদ্ধতি <a class="header-anchor" href="#৫-স্ব-পরীক্ষা-প্রক্রিয়া-এবং-ব্যবহার-পদ্ধতি" aria-label="Permalink to &quot;৫. স্ব-পরীক্ষা প্রক্রিয়া এবং ব্যবহার পদ্ধতি&quot;">​</a></h2><h3 id="৫-১-নতুন-সেটিং-তৈরির-স্ব-পরীক্ষা-প্রক্রিয়া" tabindex="-1">৫.১ নতুন সেটিং তৈরির স্ব-পরীক্ষা প্রক্রিয়া <a class="header-anchor" href="#৫-১-নতুন-সেটিং-তৈরির-স্ব-পরীক্ষা-প্রক্রিয়া" aria-label="Permalink to &quot;৫.১ নতুন সেটিং তৈরির স্ব-পরীক্ষা প্রক্রিয়া&quot;">​</a></h3><ol><li><strong>প্রাথমিক স্ব-পরীক্ষা</strong>: তৈরি সম্পন্ন হওয়ার পর, স্রষ্টা এই স্ব-পরীক্ষা টেবিলের সাথে প্রতিটি আইটেম পরীক্ষা করে, সমস্যা বিদ্যমান আইটেম চিহ্নিত করে।</li><li><strong>সংশোধন এবং পরিপূর্ণতা</strong>: চিহ্নিত সমস্যা আইটেম সংশোধন করে, সমস্ত পাস নিশ্চিত করে।</li><li><strong>ক্রস-অডিট</strong>: অন্য একজন সেটিং স্রষ্টার কাছে ক্রস-অডিটের জন্য জমা দিন, বিশেষ করে ক্রস-মডিউল সামঞ্জস্য পরীক্ষা করুন।</li><li><strong>কমিটির অনুমোদন</strong>: গুরুত্বপূর্ণ সেটিং পরিবর্তন অবশ্যই সেটিং রক্ষণাবেক্ষণ কমিটির কাছে অনুমোদনের জন্য জমা দিতে হবে।</li><li><strong>আর্কাইভ এবং আপডেট</strong>: সমস্ত পরীক্ষা পাস করার পর, আনুষ্ঠানিকভাবে সেটিং সিস্টেমে অন্তর্ভুক্ত করা হয় এবং সম্পর্কিত সূচক নথি আপডেট করা হয়।</li></ol><h3 id="৫-২-পুরানো-সেটিং-সংশোধনের-স্ব-পরীক্ষা-প্রক্রিয়া" tabindex="-1">৫.২ পুরানো সেটিং সংশোধনের স্ব-পরীক্ষা প্রক্রিয়া <a class="header-anchor" href="#৫-২-পুরানো-সেটিং-সংশোধনের-স্ব-পরীক্ষা-প্রক্রিয়া" aria-label="Permalink to &quot;৫.২ পুরানো সেটিং সংশোধনের স্ব-পরীক্ষা প্রক্রিয়া&quot;">​</a></h3><ol><li><strong>প্রভাব মূল্যায়ন</strong>: সংশোধিত বিষয়বস্তু সম্ভাব্যভাবে প্রভাবিত অন্য নথি এবং সেটিং মডিউল মূল্যায়ন করুন।</li><li><strong>সম্পর্কিত পরীক্ষা</strong>: সমস্ত প্রভাবিত সম্পর্কিত নথির সামঞ্জস্য পরীক্ষা করুন।</li><li><strong>সিঙ্ক্রোনাস সংশোধন</strong>: সম্পর্কিত নথিতে প্রভাবিত বিষয়বস্তু সিঙ্ক্রোনাসভাবে সংশোধন করুন।</li><li><strong>সংস্করণ রেকর্ড</strong>: নথি 99 &quot;নথির সংস্করণ এবং রক্ষণাবেক্ষণ বিবরণ&quot; এ সংশোধিত বিষয়বস্তু এবং সংস্করণ নম্বর রেকর্ড করুন।</li><li><strong>ঘোষণা এবং বিজ্ঞপ্তি</strong>: গুরুত্বপূর্ণ সংশোধন অবশ্যই সমস্ত সেটিং ব্যবহারকারীদের কাছে পরিবর্তনের ঘোষণা প্রকাশ করতে হবে।</li></ol><h3 id="৫-৩-নিয়মিত-সম্পূর্ণ-স্ব-পরীক্ষা" tabindex="-1">৫.৩ নিয়মিত সম্পূর্ণ স্ব-পরীক্ষা <a class="header-anchor" href="#৫-৩-নিয়মিত-সম্পূর্ণ-স্ব-পরীক্ষা" aria-label="Permalink to &quot;৫.৩ নিয়মিত সম্পূর্ণ স্ব-পরীক্ষা&quot;">​</a></h3><p>সেটিং রক্ষণাবেক্ষণ কমিটি প্রতি ত্রৈমাসিকে একবার সম্পূর্ণ সেটিং সামঞ্জস্য স্ব-পরীক্ষা করে, সমস্ত 100টি নথির পদ্ধতিগত পরীক্ষা করে, সম্ভাব্য সেটিং দ্বন্দ্ব এবং যৌক্তিক অসঙ্গতি সনাক্ত করে। স্ব-পরীক্ষার ফলাফল &quot;ত্রৈমাসিক সেটিং সামঞ্জস্য রিপোর্ট&quot; আকারে প্রকাশিত হয়, সমস্ত সেটিং ব্যবহারকারীদের কাছে খোলা থাকে।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>সেটিং দ্বন্দ্ব স্ব-পরীক্ষা টেবিল হলো অ্যাঙ্কর সিম্বায়োসিস সভ্যতার সেটিং সিস্টেমের &quot;মানের সংবিধান&quot;। এটি পদ্ধতিগত, তালিকাভুক্ত পরীক্ষা আইটেমের মাধ্যমে, নিশ্চিত করে যে সেটিং সিস্টেম ক্রমাগত সম্প্রসারণ এবং সংশোধনের প্রক্রিয়ায় সর্বদা যৌক্তিক স্ব-সামঞ্জস্য এবং শব্দার্থের ঐক্য বজায় রাখে। একটি বিশাল সেটিং সিস্টেমের সবচেয়ে ভয়ঙ্কর বিষয় হলো বিষয়বস্তু পর্যাপ্ত সমৃদ্ধ না হওয়া নয়, বরং অভ্যন্তরীণ দ্বন্দ্ব বিকশিত হওয়া এবং আগে-পরে অসঙ্গতিপূর্ণ হওয়া। এই স্ব-পরীক্ষা টেবিলের অস্তিত্ব, হলো যাতে অ্যাঙ্কর সিম্বায়োসিস সভ্যতার সেটিং সিস্টেম উন্মুক্ততা এবং বৃদ্ধিশীলতা বজায় রাখার সাথে সাথে, সর্বদা একটি দৃঢ় সামঞ্জস্যের ভিত্তি থাকে।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>99-নথির সংস্করণ এবং রক্ষণাবেক্ষণ বিবরণ</li><li>90-পরিভাষা অভিধান</li><li>00-হেঙ্গুয়ানঝো মহাবিশ্বের সারসংক্ষেপ</li></ul>',33)])])}const c=d(e,[["render",h]]);export{s as __pageData,c as default};
